FROM sd_notification n
JOIN sd_ticket t
  ON t.id = n.ticket_id
JOIN sd_ticket_event e
  ON e.id = n.event_id
WHERE n.recipient_id = #{actor.ownerId}


    AND t.requester_id = #{actor.ownerId}
    AND t.customer_id = #{actor.organizationId}
    AND e.visibility = 'PUBLIC'


    AND t.customer_id IN

      #{id}



    AND 1 = 0
